insert into permission(code,description) values('social_media.publish','Publish artwork to connected social destinations') on conflict(code) do nothing;
insert into role_permission(role_id,permission_id) select r.id,p.id from role r cross join permission p where r.code in('OWNER','MANAGER') and p.code='social_media.publish' on conflict do nothing;
create table social_media_asset(
 id bigint generated by default as identity primary key, public_id uuid not null unique,
 dealership_id bigint not null references dealership(id), created_by_staff_user_id bigint not null,
 mime_type varchar(100) not null check(mime_type='image/jpeg'), byte_length bigint not null check(byte_length>0 and byte_length<=4500000),
 sha256 char(64) not null, width integer not null check(width between 1 and 6000), height integer not null check(height between 1 and 6000),
 storage_key varchar(300) not null unique, status varchar(16) not null default 'ACTIVE' check(status in('ACTIVE','ARCHIVED')),
 created_at timestamptz not null default now(), constraint uq_social_media_asset_id_dealership unique(id,dealership_id),
 constraint fk_social_media_asset_creator_same_dealership foreign key(dealership_id,created_by_staff_user_id) references staff_user(dealership_id,id),
 check(width::bigint*height::bigint<=16000000)
);
create index ix_social_media_asset_dealership_created on social_media_asset(dealership_id,created_at desc);
create table social_media_publish_job(
 id bigint generated by default as identity primary key, public_id uuid not null unique,
 dealership_id bigint not null references dealership(id), destination_id bigint not null, asset_id bigint not null, created_by_staff_user_id bigint not null,
 provider varchar(20) not null check(provider='META'), destination_type varchar(32) not null check(destination_type in('FACEBOOK_PAGE','INSTAGRAM_PROFESSIONAL')),
 caption varchar(2200) not null default '', idempotency_key varchar(120) not null, request_fingerprint char(64) not null,
 status varchar(16) not null default 'PROCESSING' check(status in('PROCESSING','PUBLISHED','FAILED','UNKNOWN')),
 provider_container_id varchar(160), external_post_id varchar(200), error_code varchar(120),
 attempt_count integer not null default 0 check(attempt_count>=0), next_attempt_at timestamptz not null default now(), poll_lock_until timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), published_at timestamptz,
 constraint uq_social_media_publish_id_dealership unique(id,dealership_id),
 constraint uq_social_media_publish_idempotency unique(dealership_id,idempotency_key),
 constraint fk_social_publish_destination_same_dealership foreign key(destination_id,dealership_id) references social_media_destination(id,dealership_id),
 constraint fk_social_publish_asset_same_dealership foreign key(asset_id,dealership_id) references social_media_asset(id,dealership_id),
 constraint fk_social_publish_creator_same_dealership foreign key(dealership_id,created_by_staff_user_id) references staff_user(dealership_id,id)
);
create index ix_social_media_publish_poll on social_media_publish_job(status,destination_type,next_attempt_at) where status='PROCESSING';
create index ix_social_media_publish_dealership_created on social_media_publish_job(dealership_id,created_at desc);
